display.text:
#[cfg(test)]
use std::ffi::OsStr;

#[cfg(test)]
use super::SyntaxMapping;

#[derive(Debug, Clone)]
pub struct IgnoredSuffixes<'a> {
    editor_suffixes: Vec<&'a str>,
    dpkg_suffixes: Vec<&'a str>,
    ucf_suffixes: Vec<&'a str>,
    redhat_suffixes: Vec<&'a str>,
    build_suffixes: Vec<&'a str>,
}

impl Default for IgnoredSuffixes<'_> {
    fn default() -> Self {
        Self {
            editor_suffixes: vec![
                // Editor etc backups
                "~",
                ".bak",
                ".old",
                ".orig",
            ],
            dpkg_suffixes: vec![
                // Debian and derivatives apt/dpkg backups
                ".dpkg-dist",
                ".dpkg-old",
            ],
            ucf_suffixes: vec![
                // Debian and derivatives ucf backups
                ".ucf-dist",
                ".ucf-new",
                ".ucf-old",
            ],
            redhat_suffixes: vec![
                // Red Hat and derivatives rpm backups
                ".rpmnew",
                ".rpmorig",
                ".rpmsave",
            ],
            build_suffixes: vec![
                // Build system input/template files
                ".in",
            ],
        }
    }
}

impl<'a> IgnoredSuffixes<'a> {
    pub(crate) fn editor_suffixes(&self) -> &[&'a str] {
        &self.editor_suffixes
    }

    pub(crate) fn dpkg_suffixes(&self) -> &[&'a str] {
        &self.dpkg_suffixes
    }

    pub(crate) fn ucf_suffixes(&self) -> &[&'a str] {
        &self.ucf_suffixes
    }

    pub(crate) fn redhat_suffixes(&self) -> &[&'a str] {
        &self.redhat_suffixes
    }

    pub(crate) fn build_suffixes(&self) -> &[&'a str] {
        &self.build_suffixes
    }
}

#[test]
fn internal_suffixes() {
    let mapping = SyntaxMapping::empty();

    let file_names = mapping
        .ignored_suffixes
        .editor_suffixes()
        .iter()
        .chain(mapping.ignored_suffixes.dpkg_suffixes())
        .chain(mapping.ignored_suffixes.ucf_suffixes())
        .chain(mapping.ignored_suffixes.redhat_suffixes())
        .chain(mapping.ignored_suffixes.build_suffixes())
        .chain(mapping.extra_suffixes.iter())
        .map(|suffix| format!("test.json{}", suffix));
    for file_name_str in file_names {
        let file_name = OsStr::new(&file_name_str);
        let expected_stripped_file_name = OsStr::new("test.json");
        let stripped_file_name = mapping.try_with_stripped_suffix(file_name, |stripped_file_name| {
            Ok(Some(stripped_file_name.to_os_string()))
        });
        assert_eq!(
            expected_stripped_file_name,
            stripped_file_name.unwrap().unwrap()
        );
    }
}

#[test]
fn external_suffixes() {
    let mut mapping = SyntaxMapping::empty();
    mapping.insert_ignored_suffix(".development");
    mapping.insert_ignored_suffix(".production");

    let file_names = mapping
        .ignored_suffixes
        .editor_suffixes()
        .iter()
        .chain(mapping.ignored_suffixes.dpkg_suffixes())
        .chain(mapping.ignored_suffixes.ucf_suffixes())
        .chain(mapping.ignored_suffixes.redhat_suffixes())
        .chain(mapping.ignored_suffixes.build_suffixes())
        .chain(mapping.extra_suffixes.iter())
        .map(|suffix| format!("test.json{}", suffix));
    for file_name_str in file_names {
        let file_name = OsStr::new(&file_name_str);
        let expected_stripped_file_name = OsStr::new("test.json");
        let stripped_file_name = mapping.try_with_stripped_suffix(file_name, |stripped_file_name| {
            Ok(Some(stripped_file_name.to_os_string()))
        });
        assert_eq!(
            expected_stripped_file_name,
            stripped_file_name.unwrap().unwrap()
        );
    }
}

